import { createScrollspy } from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createMemo, For, onSettled, untrack } from "solid-js";

import { t } from "./theme.ts" with { type: "cssints" };

/** One heading of the page: its `id`, the link's text, and how deep it sits. */
export interface ScrollspyEntry {
  /** The heading's `id`, which the link targets. */
  readonly id: string;
  /** The link's text. */
  readonly text: string;
  /** The heading's rank, 1 for the outermost; each step indents the link once. @default 1 */
  readonly level?: number | undefined;
}

export interface ScrollspyProps {
  /** The table of contents, in document order. The headings carry these ids. */
  readonly entries: ReadonlyArray<ScrollspyEntry>;
  /**
   * The scroll container the primitive watches; the document by default. Read once, when the component settles, so a
   * swapped container needs a new `Scrollspy` (the primitive's `root` is read once too).
   */
  readonly root?: (() => HTMLElement | undefined) | undefined;
  /**
   * How far below the scrollport's top edge a heading counts as current, in px: a sticky header's height inside that
   * container. @default 0
   */
  readonly offset?: number | undefined;
  /** The navigation landmark's accessible name. @default "Table of contents" */
  readonly label?: string | undefined;
  /** The current id changed. */
  readonly onChange?: ((id: string | undefined) => void) | undefined;
  readonly class?: string | undefined;
}

const navClass = css.cn(css.fontSize(t.font.size), css.color(t.color.text));

// The rule the current link sits on: the list draws it, and the link's own border covers it in the accent, so the marker
// is a 1px inset that does not move the text when the current entry changes.
const listClass = css.cn(
  css.margin("0"),
  css.padding("0"),
  css.listStyle("none"),
  css.borderInlineStart("1px solid", t.color.border),
);

const linkClass = css.cn(
  css.display("block"),
  css.marginInlineStart("-1px"),
  css.paddingBlock(t.space._1),
  css.paddingInlineEnd(t.space._3),
  css.borderInlineStart("1px solid", "transparent"),
  css.color(t.color.muted),
  css.lineHeight(1.4),
  css.textDecoration("none"),
  // the state is the primitive's attribute, not a prop: the link the reader is at is the one it marked
  css.attr("aria-current", "location")(
    css.color(t.color.text),
    css.fontWeight("500"),
    css.borderInlineStartColor(t.color.highlight),
  ),
  css.hover(css.color(t.color.text)),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("-2px")),
);

/** The entries' levels as an indent: a step is one `space-3`, and the outermost heading keeps it too. */
const indent = (level: number | undefined): JSX.CSSProperties => ({
  "padding-inline-start": `calc(var(--space-3) * ${Math.max(1, level ?? 1)})`,
});

/**
 * A table of contents over `createScrollspy`: a named navigation landmark, one link per entry and the current one marked
 * `aria-current="location"`. The primitive owns the observation (one passive scroll listener on `root()`, the document by
 * default), the "last heading at or above the offset" rule and the one-current-link invariant; the skin owns the list, the
 * indent from each entry's level, and the left rule painted from `aria-current` in the theme's tokens.
 *
 * The links are plain `#id` targets, so the scrollport moves itself and smooth scrolling is the page's (`scroll-behavior`).
 * A heading below the list's first is not current until its top passes the container's offset line; before any scroll, the
 * first entry is.
 */
export const Scrollspy = (props: ScrollspyProps): JSX.Element => {
  // a new array per change of the caller's list, so the primitive's scroll listener reads the current entries
  const entries = createMemo(() =>
    props.entries.map((entry) => ({ id: entry.id, label: entry.text })),
  );
  const spy = createScrollspy({
    // untracked: the primitive reads the entries once at construction and again on every scroll, outside any computation
    get entries() {
      return untrack(entries);
    },
    get offset() {
      return props.offset;
    },
    get root() {
      return props.root;
    },
    get onChange() {
      return props.onChange;
    },
  });
  // `attach` wires the one listener and returns its teardown, which Solid runs on cleanup
  onSettled(() => spy.attach());

  return (
    <nav
      {...spy.navProps}
      aria-label={props.label ?? "Table of contents"}
      data-part="scrollspy"
      class={css.cn(navClass, props.class)}
    >
      <ul {...spy.listProps} data-part="scrollspy-list" class={listClass}>
        <For each={props.entries}>
          {(entry) => (
            <li {...spy.itemProps(entry.id)}>
              <a
                {...spy.linkProps(entry.id)}
                data-part="scrollspy-link"
                class={linkClass}
                style={indent(entry.level)}
              >
                {entry.text}
              </a>
            </li>
          )}
        </For>
      </ul>
    </nav>
  );
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { render } from "@solidjs/web";
import { createSignal, For } from "solid-js";

import { Scrollspy, type ScrollspyEntry } from "./scrollspy.tsx";

/** The heading a section starts with; the levels are what the list indents by. */
interface Section {
  readonly id: string;
  readonly text: string;
  readonly level: number;
  readonly body: string;
}

const SECTIONS: ReadonlyArray<Section> = [
  {
    id: "scrollspy-overview",
    text: "Overview",
    level: 1,
    body: "A table of contents beside an article: the link of the heading that last passed the top of the pane is current.",
  },
  {
    id: "scrollspy-install",
    text: "Install",
    level: 2,
    body: "The package, the theme and the plugin. This heading is below the fold until the pane scrolls.",
  },
  {
    id: "scrollspy-configure",
    text: "Configure",
    level: 2,
    body: "The entries in document order, the container the primitive listens on, and the offset of a sticky header.",
  },
  {
    id: "scrollspy-deploy",
    text: "Deploy",
    level: 1,
    body: "The last section is not in the table until a page adds it: the entries are read again on every scroll.",
  },
];

/** The table before any change: the page lists its first three headings. */
export const SCROLLSPY_ENTRIES: ReadonlyArray<ScrollspyEntry> = SECTIONS.slice(0, 3).map(
  ({ id, text, level }) => ({ id, text, level }),
);

/** The entry a page adds later: its heading is already in the article, the table has not read it yet. */
export const SCROLLSPY_LAST: ScrollspyEntry = { id: "scrollspy-deploy", text: "Deploy", level: 1 };

/** The pane's height, so a section (and the heading after it) starts below the fold. */
const PANE_HEIGHT = 260;

/** One section's height: taller than the pane, so only one heading is at the top at a time. */
const SECTION_HEIGHT = 300;

/** What a mounted demo hands the test: the pane it scrolls, a way to grow the table, and a teardown. */
export interface MountedScrollspy {
  readonly root: HTMLElement;
  /** The scroll container the primitive watches. */
  readonly pane: HTMLElement;
  /** Adds the last section to the table, the way a page grows its outline. */
  readonly reveal: () => void;
  readonly dispose: () => void;
}

/**
 * Mounts the styled table of contents in ordinary use: an article with four sections in a 260 px scroll pane, and the table
 * beside it. The pane is what the primitive listens on, so the demo works inside the docs preview without the page
 * scrolling; `reveal()` shows the entries changing.
 */
export const mountScrollspy = (): MountedScrollspy => {
  const root = document.createElement("div");
  document.body.append(root);
  let pane!: HTMLDivElement;
  const [entries, setEntries] = createSignal<ReadonlyArray<ScrollspyEntry>>(SCROLLSPY_ENTRIES);

  const dispose = render(
    () => (
      <div
        data-part="scrollspy-demo"
        style={{
          display: "flex",
          gap: "24px",
          "align-items": "flex-start",
          width: "720px",
        }}
      >
        <div
          data-part="scrollspy-pane"
          ref={pane}
          style={{
            height: `${PANE_HEIGHT}px`,
            width: "420px",
            "overflow-y": "auto",
            padding: "0 16px",
            // no border: the primitive measures the heading against the scrollport's top, and a 1px border would leave a
            // fragment-scrolled heading 1px short of the line. The ring is a shadow, so the box model stays the scrollport's.
            "box-shadow": "inset 0 0 0 1px #d0d0d0",
            "border-radius": "8px",
            "box-sizing": "border-box",
          }}
        >
          <For each={SECTIONS}>
            {(section) => (
              <section style={{ height: `${SECTION_HEIGHT}px`, padding: "0", margin: "0" }}>
                <h2 id={section.id} style={{ margin: "0", "font-size": "18px" }}>
                  {section.text}
                </h2>
                <p style={{ margin: "8px 0 0", color: "#555" }}>{section.body}</p>
              </section>
            )}
          </For>
        </div>
        <div style={{ width: "200px" }}>
          <p style={{ margin: "0 0 8px", "font-size": "12px", color: "#666" }}>On this page</p>
          <Scrollspy entries={entries()} root={() => pane} />
        </div>
      </div>
    ),
    root,
  );

  return {
    root,
    pane,
    reveal: () => setEntries([...SCROLLSPY_ENTRIES, SCROLLSPY_LAST]),
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { afterEach, describe, expect, it } from "vite-plus/test";

import { type MountedScrollspy, mountScrollspy } from "./scrollspy.fixture";

// No APG pattern and no Quint spec exists for a scrollspy, so this file is the skin's oracle: it mounts the starter in a
// real Chromium and scrolls the same pane a reader does. The accessible contract (a named landmark, one `aria-current`
// link, ids as the headings' targets) is only observable through the DOM.
//
// The fixture's pane is 260 px tall and every section is 300, so one heading is at the top of the pane at a time and the
// next starts below the fold.

/** Solid applies setters on the next flush, and a scroll event lands on a later turn: two frames settle both. */
const frame = (): Promise<void> =>
  new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));

/** Polls until `done` holds, so a slow frame on a busy machine is waited for rather than assumed. */
const waitFor = async (done: () => boolean, limit = 5000): Promise<void> => {
  const start = performance.now();
  while (!done()) {
    if (performance.now() - start > limit) {
      throw new Error("waitFor timed out");
    }
    await frame();
  }
};

const live: MountedScrollspy[] = [];

const mounted = (): MountedScrollspy => {
  const instance = mountScrollspy();
  live.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

const nav = (root: ParentNode): HTMLElement => {
  const element = root.querySelector<HTMLElement>('nav[data-part="scrollspy"]');
  if (element === null) {
    throw new Error("scrollspy: no nav");
  }
  return element;
};

const links = (root: ParentNode): HTMLAnchorElement[] => [
  ...nav(root).querySelectorAll<HTMLAnchorElement>('a[data-part="scrollspy-link"]'),
];

const current = (root: ParentNode): HTMLAnchorElement[] => [
  ...nav(root).querySelectorAll<HTMLAnchorElement>('a[aria-current="location"]'),
];

const heading = (id: string): HTMLElement => {
  const element = document.getElementById(id);
  if (element === null) {
    throw new Error(`scrollspy: no heading ${id}`);
  }
  return element;
};

/** A heading's top in the pane's own coordinates. */
const topOf = (mountedInstance: MountedScrollspy, id: string): number => {
  const pane = mountedInstance.pane.getBoundingClientRect();
  return heading(id).getBoundingClientRect().top - pane.top + mountedInstance.pane.scrollTop;
};

const scrollTo = async (mountedInstance: MountedScrollspy, top: number): Promise<void> => {
  mountedInstance.pane.scrollTop = top;
  await waitFor(() => Math.abs(mountedInstance.pane.scrollTop - top) <= 1);
  await frame();
};

describe("Scrollspy", () => {
  it("is a named landmark that lists the entries, the first one current", () => {
    const { root } = mounted();
    const items = links(root);

    expect(nav(root).tagName).toBe("NAV");
    expect(nav(root).getAttribute("aria-label")).toBe("Table of contents");
    expect(nav(root).querySelector("ul")?.getAttribute("role")).toBe("list");
    expect(items.map((link) => link.textContent)).toEqual(["Overview", "Install", "Configure"]);
    expect(items.map((link) => link.getAttribute("href"))).toEqual([
      "#scrollspy-overview",
      "#scrollspy-install",
      "#scrollspy-configure",
    ]);
    expect(items.map((link) => link.closest("li")?.getAttribute("role"))).toEqual([
      "listitem",
      "listitem",
      "listitem",
    ]);

    const currentLinks = current(root);
    expect(currentLinks).toHaveLength(1);
    expect(currentLinks[0]?.getAttribute("href")).toBe("#scrollspy-overview");
    expect(items[1]?.hasAttribute("aria-current")).toBe(false);
  });

  it("indents a nested entry by its level", () => {
    const { root } = mounted();
    const [outer, nested] = links(root);
    expect(outer).toBeDefined();
    expect(nested).toBeDefined();
    const padding = (link: HTMLAnchorElement | undefined): number =>
      Number.parseFloat(getComputedStyle(link as HTMLAnchorElement).paddingInlineStart);

    expect(padding(nested)).toBeGreaterThan(padding(outer));
  });

  it("moves aria-current to the heading that passed the top, and only one has it", async () => {
    const instance = mounted();
    const { root } = instance;

    // the heading of Configure at the top of the pane: it is the last one at or above the line
    await scrollTo(instance, topOf(instance, "scrollspy-configure") + 40);
    await waitFor(() => current(root)[0]?.getAttribute("href") === "#scrollspy-configure");

    expect(current(root)).toHaveLength(1);
    expect(current(root)[0]?.textContent).toBe("Configure");

    await scrollTo(instance, topOf(instance, "scrollspy-install") + 40);
    await waitFor(() => current(root)[0]?.getAttribute("href") === "#scrollspy-install");
    expect(current(root)).toHaveLength(1);
  });

  it("keeps a heading below the fold out of the table of contents until the pane scrolls", () => {
    const instance = mounted();
    const paneBox = instance.pane.getBoundingClientRect();
    const install = heading("scrollspy-install").getBoundingClientRect();

    expect(install.top).toBeGreaterThanOrEqual(paneBox.top + instance.pane.clientHeight);
    expect(current(instance.root)[0]?.getAttribute("href")).toBe("#scrollspy-overview");
  });

  it("scrolls the pane to the heading when its link is clicked, and marks it current", async () => {
    const instance = mounted();
    const paneBox = instance.pane.getBoundingClientRect();

    links(instance.root)[2]?.click();
    await waitFor(() => {
      const box = heading("scrollspy-configure").getBoundingClientRect();
      return box.top >= paneBox.top - 1 && box.top < paneBox.bottom;
    });

    expect(instance.pane.scrollTop).toBeGreaterThan(0);
    await waitFor(() => current(instance.root)[0]?.getAttribute("href") === "#scrollspy-configure");
  });

  it("re-reads the list and the headings when the entries change", async () => {
    const instance = mounted();
    expect(links(instance.root)).toHaveLength(3);

    instance.reveal();
    await waitFor(() => links(instance.root).length === 4);
    expect(links(instance.root)[3]?.textContent).toBe("Deploy");

    await scrollTo(instance, topOf(instance, "scrollspy-deploy") + 40);
    await waitFor(() => current(instance.root)[0]?.getAttribute("href") === "#scrollspy-deploy");
    expect(current(instance.root)).toHaveLength(1);
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
